import{_ as o,o as c,c as d,a5 as F}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"UTF8、UTF16、UTF32","description":"都是 unicode 字符集的字符编码。 UTF 意思是 unicode 转换格式（ Unicode transform format ），出现 UTF8 、 UTF16 、 UTF32 是出于要在内存中存储字符的目的而对 unicode 字符编号进行编码。 UTF8 、 UTF。","frontmatter":{"title":"UTF8、UTF16、UTF32","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"都是 unicode 字符集的字符编码。 UTF 意思是 unicode 转换格式（ Unicode transform format ），出现 UTF8 、 UTF16 、 UTF32 是出于要在内存中存储字符的目的而对 unicode 字符编号进行编码。 UTF8 、 UTF。","sidebarWeight":30,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/基本数据类型-字符串/字符串的表示方式/UTF8、UTF16、UTF32.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/字符串的表示方式/UTF8、UTF16、UTF32.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/字符串的表示方式/UTF8、UTF16、UTF32.md"}'),t={name:"posts/JavaScript系统教程/02-语法、变量与数据/字符串的表示方式/UTF8、UTF16、UTF32.md"};function U(T,e,a,i,n,r){return c(),d("div",null,[...e[0]||(e[0]=[F('<div><h1 id="utf8、utf16、utf32" tabindex="-1">UTF8、UTF16、UTF32 <a class="header-anchor" href="#utf8、utf16、utf32" aria-label="Permalink to &quot;UTF8、UTF16、UTF32&quot;">​</a></h1><blockquote><p>本节目标：理解“UTF8、UTF16、UTF32”的核心思路，并能把它用于实际开发或面试表达。 都是<code>unicode</code>字符集的字符编码。</p></blockquote><p><code>UTF</code>意思是<code>unicode</code>转换格式（<code>Unicode transform format</code>），出现<code>UTF8</code>、<code>UTF16</code>、<code>UTF32</code>是出于要在内存中存储字符的目的而对<code>unicode</code>字符编号进行编码。</p><p><code>UTF8</code>、<code>UTF16</code>、<code>UTF32</code>区别：（<code>8</code>、<code>16</code>、<code>32</code>可看做每种字符编码存储所需的最少的比特位数）</p><p><code>UTF8</code>：存在单字节编码，兼容<code>ASCII</code>；当编码为一个字节，则设最高比特位为<code>0</code>；当编码超过一个字节，则需要几个字节，就在第一个字节从最高位开始令连续的几个比特位为<code>1</code>，之后的字节最高位为<code>10</code>。</p><p><code>UTF32</code>：用固定长度的字节存储字符编码，不管<code>Unicode</code>字符编号需要几个字节，全部都用<code>4</code>个字节存储，直接存储<code>Unicode</code>编号。无需经过字符编号向字符编码的转换步骤，提高效率，用空间换时间。</p><p><code>UTF16</code>：使用<code>2</code>或<code>4</code>个字节进行存储。对于<code>Unicode</code>编号范围在<code>0~FFFF</code>之间的字符，统一用两个字节存储，无需字符转换，直接存储<code>Unicode</code>编号。对于<code>Unicode</code>字符编号在<code>10000-10FFFF</code>之间的字符，<code>UTF16</code>用四个字节存储，简单说就是：将<code>Unicode</code>字符编号<code>(3</code>字节<code>)</code>分为两部分，高位部分（<code>Unicode</code>字符编号中占<code>1.5</code>个字节）用一个值介于 <code>D800-DBFF</code> （<code>110110yy yyyyyyyy</code>，<code>y</code>为<code>0/1</code>）之间的双字节存储，低位部分用一个值介于 <code>DC00-DFFF</code> （<code>110111xx xxxxxxxx</code>，<code>x</code>为<code>0/1</code>）的双字节存储。而介于<code>D800-DFFF</code>之间的编码在<code>Unicode</code>中是预留的，不安排字符，如果<code>Unicode</code>中有字符的编号是这之间的值，会引发冲突和歧义，很有可能一个不常见字符（存储为四个字节）最后被读成两个常见字符（存储为两个字节）。</p></div>',1)])])}const u=o(t,[["render",U]]);export{p as __pageData,u as default};
